// Biomedical Debate Practice Test 2. Original questions written for Valus on the 2026–27 resolution,
// "Limited healthcare resources should be allocated to patients with the greatest likelihood of
// long-term survival." Slightly harder than the sample items. Content follows the Valus Biomedical
// Debate lessons and the published allocation literature they cite.
import {q, mix} from './q.js';
const LEVY='Levy, Breaking the Age Code (2022)', BH='Bognar & Hirose, The Ethics of Health Care Rationing', EMAN='Emanuel et al., NEJM (2020)', PERSAD='Persad, Wertheimer & Emanuel, The Lancet (2009)', OPTN='Organ Procurement and Transplantation Network';
const SCAR='Scarcity and Levels of Allocation', ETH='Ethical Theories and Principles', CRIT='Allocation Criteria and Frameworks', CASE='Real-World Allocation Cases', AGE='Aging, Longevity and Equity';

export default {
 id:'biomedical-debate-2',
 event:'Biomedical Debate',
 title:'Practice Test 2',
 subtitle:'Round One test simulation on the 2026–27 resolution',
 minutes:60,
 sources:'Levy’s Breaking the Age Code, Bognar and Hirose’s The Ethics of Health Care Rationing and published allocation frameworks',
 plan:[{area:'Resolution: Allocating Limited Healthcare Resources',weight:100,topics:[SCAR,ETH,CRIT,CASE,AGE]}],
 questions:mix([
  q(SCAR,'A national government decides what share of its budget goes to health care versus education. What level of allocation is this?','Macroallocation',['Microallocation','Bedside rationing','Triage'],'A','Macroallocation decides how much is spent on health and on which broad programs; microallocation decides which individual patients receive a resource.',BH),
  q(SCAR,'Which is an example of explicit rationing?','A published list of which treatments a plan will cover',['A clinician quietly not mentioning a costly option','Long waits that discourage patients from seeking care','Clinics that are hard to reach by public transit'],'B','Explicit rationing states its limits openly through public rules; implicit rationing limits care through hidden decisions, delays or barriers.',BH),
  q(SCAR,'Higher copayments that discourage patients from using some services are an example of rationing by what?','Price',['Lottery','Queue','Medical need'],'C','Cost sharing allocates care by willingness and ability to pay, which critics say burdens low-income patients most.',BH),
  q(SCAR,'Intensive care beds run short because there are not enough trained nurses, though more could be hired over time. What kind of scarcity is this?','Relative scarcity',['Absolute scarcity','Artificial scarcity','Permanent scarcity'],'D','Relative scarcity could be eased with more money, staff or time; absolute scarcity, such as deceased-donor organs, cannot simply be bought.',BH),
  q(SCAR,'On the surge capacity continuum, which level provides care that is “functionally equivalent” to usual care?','Contingency capacity',['Conventional capacity','Crisis capacity','Disaster capacity'],'A','Conventional care is usual care, contingency care adapts spaces and staff while staying functionally equivalent, and crisis care changes the standard.',BH),
  q(SCAR,'Which military surgeon is credited with developing early battlefield triage in Napoleon’s army?','Dominique-Jean Larrey',['Joseph Lister of Glasgow','Ambroise Paré of France','John Snow of London'],'B','Larrey treated the wounded by medical urgency rather than rank, an early form of the triage principles used in disasters today.',BH),
  q(SCAR,'Why do critics object to “bedside rationing” by a patient’s own physician?','It conflicts with the physician’s duty to the patient',['It is always more expensive than committee decisions','It is illegal in every U.S. state','It relies too heavily on published data'],'C','Many ethicists argue that rationing rules should be set by policy, not by the treating clinician, to protect trust and avoid bias.',BH),
  q(SCAR,'A health system spends $2 million on one experimental treatment instead of vaccinating thousands of children. Which concept does this illustrate?','Opportunity cost',['Sunk cost','Moral hazard','Adverse selection'],'D','Every allocation has an opportunity cost: the benefits that the same resources could have produced if used for something else.',BH),
  q(ETH,'Rawls’s “veil of ignorance” asks people to choose principles of justice without knowing what?','Their own place in society',['The laws of their country','The cost of each treatment','The names of their leaders'],'A','Not knowing whether they would be rich or poor, healthy or sick, people would choose fair rules that protect the least advantaged.',BH),
  q(ETH,'Which theory holds that each person should have an equal chance at a scarce resource regardless of expected benefit?','Egalitarianism',['Utilitarianism','Prioritarianism','Libertarianism'],'B','Strict egalitarian views favor equal access or equal chances, such as lotteries, rather than ranking patients by outcomes.',BH),
  q(ETH,'A Kantian critic says allocation by survival treats some patients merely as means. Which theory is this critic using?','Deontology',['Utilitarianism','Consequentialism','Egalitarianism'],'C','Kantian deontology holds that people must be treated as ends in themselves, never merely as means to maximize total outcomes.',BH),
  q(ETH,'Which view argues that people should be free to buy health care in markets with minimal government redistribution?','Libertarianism',['Prioritarianism','Sufficientarianism','Egalitarianism'],'D','Libertarians stress individual liberty and property rights, so they generally oppose mandatory redistribution of health resources.',BH),
  q(ETH,'A treatment costs $60,000 and adds 3 QALYs. What is its cost per QALY?','$20,000',['$180,000','$30,000','$57,000'],'A','Cost per QALY = cost ÷ QALYs gained = $60,000 ÷ 3 = $20,000, which many agencies would consider good value.',BH),
  q(ETH,'How does a DALY differ from a QALY?','It measures health lost rather than health gained',['It counts only years lived with disability','It ignores deaths from disease entirely','It is used only for measuring child health'],'B','A DALY combines years of life lost to early death and years lived with disability, so lower DALY totals are better.',BH),
  q(ETH,'Which theory holds that what matters most is that everyone reaches a minimum threshold of health?','Sufficientarianism',['Classical utilitarianism','Libertarianism','Prioritarianism'],'C','Sufficientarians focus on bringing everyone above a threshold, rather than on maximizing totals or giving extra weight to the worst off.',BH),
  q(ETH,'A society spends heavily to rescue one trapped miner but little on safety programs that would save more people. What does this contrast illustrate?','Identified lives versus statistical lives',['Absolute versus relative scarcity','Explicit versus implicit rationing','Macro- versus mesoallocation'],'D','People value identifiable victims more than unnamed “statistical” lives, which can pull resources away from prevention.',BH),
  q(ETH,'Which four principles of biomedical ethics did Beauchamp and Childress describe?','Autonomy, beneficence, nonmaleficence and justice',['Utility, liberty, equality and duty to others','Honesty, loyalty, courage and charity to all','Consent, privacy, safety and efficiency'],'A','Justice is the principle most directly at stake in allocation, but debaters can show tension with beneficence and autonomy.',BH),
  q(ETH,'Clinicians who must follow triage rules that conflict with their values may experience what?','Moral distress',['Moral hazard','Moral luck','Moral realism'],'B','Moral distress occurs when people know the ethical action but feel unable to take it, a common problem during crisis standards of care.',BH),
  q(CRIT,'Persad, Wertheimer and Emanuel’s “complete lives system” gives special priority to which age group?','Adolescents and young adults',['Infants under one year of age','Adults over age 65 only','Middle-aged adults only'],'C','The system combines youngest-first, prognosis, saving the most lives and lottery, giving priority to those who have lived fewest complete years.',PERSAD),
  q(CRIT,'Which four values did Emanuel et al. (2020) identify for allocating scarce resources in the COVID-19 pandemic?','Maximize benefits, equal treatment, usefulness, worst off',['Ability to pay, age, insurance status and citizenship','First come first served, lottery, seniority and fame','Wealth, education, employment status and social standing'],'D','The authors argued that maximizing benefits should be the top priority, with the other values guiding further choices.',EMAN),
  q(CRIT,'According to Emanuel et al., may a ventilator be withdrawn from one patient to give to another with a better prognosis?','Yes, it can be justified during a true shortage',['No, never under any circumstances at all','Only if the first patient’s family agrees','Only if both patients are under age 40'],'A','The authors argued that removing a ventilator for a patient more likely to benefit is justified during scarcity and should be in policy.',EMAN),
  q(CRIT,'Why did Emanuel et al. support giving priority to participants in vaccine and treatment research?','They accept risk that benefits others',['They usually have the best prognosis','They pay for their own treatment','They are always health care workers'],'B','Priority for research participants reflects reciprocity and promotes instrumental value: their participation helps save future lives.',EMAN),
  q(CRIT,'What is the difference between medical utility and social utility in allocation?','Medical utility counts health benefit; social utility counts social worth',['Medical utility counts cost; social utility counts health benefit','They are two names for the same criterion','Medical utility applies only to organ transplants'],'C','Most frameworks accept medical utility, such as likely benefit, but reject judging people by social worth, such as job or reputation.',BH),
  q(CRIT,'Which principle gives priority to people who took on risks for others, such as front-line workers?','Reciprocity',['Sufficiency','Autonomy','Futility'],'D','Reciprocity says society owes something to those who accepted risk for the common good, separate from any future instrumental value.',EMAN),
  q(CRIT,'Why do critics argue that first-come, first-served favors some groups unfairly?','Wealthier patients often arrive first',['It always gives priority to the sickest','It requires a lottery for every patient','It is based entirely on age'],'A','Getting to the front of the line depends on transport, information and time off work, which are unequally distributed.',EMAN),
  q(CRIT,'In Persad et al.’s analysis, what role does a lottery play?','A tiebreaker among otherwise similar patients',['The main way to allocate every resource','A way to rank patients by social worth','A method used only in organ transplants'],'B','A lottery respects equal worth but ignores differences in need and benefit, so Persad et al. recommend it mainly for close cases.',PERSAD),
  q(CRIT,'An affirmative debater says the resolution maximizes benefits. Which value from Emanuel et al. is the debater relying on most?','Maximizing benefits, measured in life-years',['Treating people equally through a lottery','Giving priority to the worst off','Rewarding instrumental value to society'],'C','Prioritizing likelihood of long-term survival aims to produce the most life-years, which aligns closely with maximizing benefits.',EMAN),
  q(CRIT,'A negative debater argues survival predictions disadvantage those already in poor health because of poverty. Which value supports this?','Priority to the worst off',['Maximizing life-years saved','Instrumental value','Reciprocity'],'D','Giving priority to the worst off directs resources toward the sickest or most disadvantaged, even when expected benefit is lower.',EMAN),
  q(CRIT,'What is “instrumental value” in allocation ethics?','A person’s ability to help save others',['A person’s ability to pay for care','A person’s social status or fame','A person’s length of time on the waitlist'],'A','Instrumental value favors those, like health workers, whose recovery lets them protect or treat others; it differs from social worth.',EMAN),
  q(CASE,'In the 1960s, a Seattle committee chose dialysis patients partly by judging their “social worth.” What was it nicknamed?','The “God Committee”',['The “Death Panel”','The “Lottery Board”','The “Survival Council”'],'B','Critics attacked its use of factors such as job, church membership and family status, helping turn bioethics against social-worth criteria.',BH),
  q(CASE,'What does the MELD score estimate in liver transplant allocation?','The risk of death within 90 days without a transplant',['The expected years of life after transplant','The patient’s ability to pay for surgery','The quality of the donated liver'],'C','MELD uses lab values such as bilirubin, INR and creatinine to prioritize the sickest candidates—a need-based, not survival-based, approach.',OPTN),
  q(CASE,'In U.S. kidney allocation, what does the Estimated Post-Transplant Survival (EPTS) score predict?','How long a candidate is likely to benefit from a kidney',['How long a donor kidney will be stored before use','How far a donor kidney can safely travel','How much a transplant will cost the hospital'],'D','Candidates in the top 20% of EPTS receive priority for the top 20% of kidneys, a direct use of long-term survival in allocation.',OPTN),
  q(CASE,'Since the 2014 kidney allocation changes, how is waiting time usually counted for adult candidates?','From the start of dialysis, if before listing',['From the date of the first doctor’s visit','From the date the patient turns 18','From the date the patient pays a fee'],'A','Counting from dialysis start reduced the advantage for patients who were referred and listed earlier, often those with better access.',OPTN),
  q(CASE,'After Hurricane Katrina, which group of patients at Memorial Medical Center was reportedly evacuated last?','Patients with do-not-resuscitate orders',['Newborns in the intensive care unit','Patients who could walk unaided','Pregnant patients in labor'],'B','The decision drew criticism because a DNR order concerns resuscitation preferences, not likelihood of survival or need for evacuation.',BH),
  q(CASE,'What controversial suggestion appeared in Italy’s SIAARTI critical care guidance in March 2020?','An age limit for ICU admission might become necessary',['ICU beds should be sold to the highest bidder','All ICU admissions should be decided by lottery','Only health workers should receive ventilators'],'C','The guidance drew global debate because it suggested age-based limits, showing how survival and life-years arguments play out in practice.',BH),
  q(CASE,'The UK’s NICE has traditionally used about what threshold per QALY to judge cost-effectiveness?','£20,000–£30,000',['£500–£1,000','£2,000–£3,000','£200,000–£300,000'],'D','Treatments costing more than this range per QALY are less likely to be recommended for NHS use, an explicit form of rationing.',BH),
  q(CASE,'In 2013, a Pennsylvania court ordered that 10-year-old Sarah Murnaghan be considered for adult lungs. What rule was challenged?','The “under-12” rule for adult lungs',['The rule against multiple listing','The ban on living lung donation','The MELD score for liver allocation'],'A','The case raised whether an age-based allocation rule was fair, and OPTN later reviewed pediatric access to adult lungs.',OPTN),
  q(CASE,'How did the FDA stretch the limited mpox vaccine supply in 2022?','Allowing a smaller intradermal dose',['Requiring a lottery among all adults','Giving vaccine only to people over 65','Banning all second doses'],'B','Intradermal injection of one-fifth the usual dose produced similar immune responses, so each vial could protect up to five people.',BH),
  q(CASE,'Why did federal civil rights officials investigate Alabama’s 2020 ventilator guidelines?','They allegedly deprioritized people with disabilities',['They gave ventilators only to wealthy patients','They required ventilators to be shipped out of state','They banned hospitals from using SOFA scores'],'C','Alabama withdrew the language after complaints, showing how disability rights law limits crisis allocation criteria.',BH),
  q(CASE,'Apple founder Steve Jobs received a liver transplant in Tennessee in 2009 after listing outside his home state. What practice does this illustrate?','Multiple listing',['Directed donation','Paired exchange','Longevity matching'],'D','Multiple listing is legal, but critics note it favors patients who can afford travel and evaluations at several centers.',OPTN),
  q(AGE,'In Levy’s research, older adults with positive age beliefs were how much more likely to fully recover from severe disability?','About 44% more likely',['About 4% more likely','About 10% more likely','About 400% more likely'],'A','Levy argues age beliefs shape health outcomes, so survival predictions based on age may partly reflect ageism rather than biology.',LEVY),
  q(AGE,'Levy found that negative age beliefs were linked to which brain changes associated with Alzheimer’s disease?','More amyloid plaques and tangles',['Larger hippocampal volume over time','Faster conduction along motor nerves','Higher dopamine levels in the striatum'],'B','This finding supports stereotype embodiment theory: internalized age stereotypes can have measurable biological effects.',LEVY),
  q(AGE,'Levy estimated the yearly U.S. health care cost of ageism at about how much?','$63 billion',['$6 million','$630 million','$6 trillion'],'C','The estimate included costs linked to age discrimination, negative age stereotypes and negative self-perceptions of aging.',LEVY),
  q(AGE,'Who coined the term “ageism” in 1969?','Robert Butler',['Becca Levy','Daniel Callahan','John Rawls'],'D','Robert Butler, the first director of the National Institute on Aging, defined ageism as prejudice and discrimination based on age.',LEVY),
  q(AGE,'Why do many crisis frameworks prefer frailty or organ function to age alone?','Age is a crude proxy for prognosis',['Frailty is easier to fake than age','Age data are not kept in health records','Frailty is measured only in children'],'A','Using clinical measures avoids treating all people of the same age alike, a key negative argument against blunt age cutoffs.',LEVY),
  q(AGE,'What does Fries’s “compression of morbidity” hypothesis propose?','Illness can be delayed into fewer years late in life',['Disease always increases with longer life','All older adults become disabled at the same age','Morbidity is unrelated to lifestyle or behavior'],'B','If healthy behaviors postpone disease, people may live longer with less disability, challenging the idea that old age equals poor outcomes.',LEVY),
  q(AGE,'In 2023, the OPTN required kidney programs to adjust waiting times for Black candidates. Why?','Race-based kidney equations had delayed their listing',['Black candidates had been listed too early','Donor kidneys had been reserved for them by law','Waiting time was no longer used in allocation'],'C','Race-based eGFR equations overestimated kidney function in Black patients, delaying eligibility—an example of how criteria can embed disparities.',OPTN),
  q(AGE,'Which argument holds that each generation should receive a fair share of resources over a lifetime?','Intergenerational equity',['Stereotype embodiment','Rule of rescue','Compression of morbidity'],'D','Intergenerational equity underlies “fair innings” views, and the negative can argue it conflicts with individual rights at any age.',BH),
  q(AGE,'How could the affirmative respond to the claim that survival-based allocation is ageist?','By predicting survival from prognosis, not age',['By excluding all patients over a set age','By letting families bid for scarce resources','By ignoring the medical evidence entirely'],'A','An affirmative case is stronger when it defines survival likelihood through individualized, evidence-based assessment rather than age categories.',EMAN),
  q(AGE,'Why might a negative team cite Levy’s priming studies?','Changing age beliefs improved older adults’ physical function',['Priming studies proved age has no effect on health','Priming studies measured organ donation rates','The studies found older adults cannot change'],'B','If outcomes improve when age beliefs change, survival predictions may reflect stereotypes as much as fixed biological limits.',LEVY)
 ],4432)
};
